mapper.select:
SELECT 
    ev.id,
    ev.voucher_type,
    ev.voucher_no,
    ev.source_file_type,
    ev.source_file_size,
    ev.total_amount,
    ev.currency,
    ev.issue_date,
    ev.signature_status,
    ev.verify_status,
    ev.status,
    ev.finance_voucher_id,
    ev.create_time,
    u.name as created_by_name
FROM electronic_voucher ev
LEFT JOIN users u ON ev.created_by = u.ID
WHERE ev.deleted = 0
AND ev.tenant_id = #{tenantId}

    AND ev.voucher_no LIKE CONCAT('%', #{query.voucherNo}, '%')


    AND ev.voucher_type = #{query.voucherType}


    AND ev.status = #{query.status}


    AND ev.signature_status = #{query.signatureStatus}


    AND ev.verify_status = #{query.verifyStatus}


    AND ev.issue_date >= #{query.startDate}


    AND ev.issue_date <= #{query.endDate}


    AND ev.business_type = #{query.businessType}


    AND ev.business_id = #{query.businessId}

ORDER BY ev.create_time DESC

SELECT * FROM electronic_voucher
WHERE source_file_hash = #{fileHash}
AND tenant_id = #{tenantId}
AND deleted = 0
LIMIT 1

SELECT * FROM electronic_voucher
WHERE voucher_no = #{voucherNo}
AND tenant_id = #{tenantId}
AND deleted = 0
LIMIT 1

SELECT * FROM electronic_voucher
WHERE tenant_id = #{tenantId}
AND total_amount = #{totalAmount}
AND issue_date = #{issueDate}
AND deleted = 0
ORDER BY create_time DESC
